    "questionNumber": 136,
    "question": "A woman has a regular menstrual cycle length of 26 days. Based on the 14-day luteal phase principle, on which day of her cycle is ovulation most likely to occur, and what is the corresponding fertile window (periodic abstinence window)?",
    "options": {
      "A": "Ovulation on Day 21, fertile window Day 1-5",
      "B": "Ovulation on Day 14 regardless of cycle length, fertile window Day 10-17",
      "C": "Ovulation on Day 12, fertile window from Day 9 to Day 15",
      "D": "Ovulation on Day 17, fertile window Day 20-28"
    },
