    "correctAnswer": "C",
    "correctOption": "C",
    "correctIndex": 2,
    "explanation": "1. CONCEPT:\nCalculating fertile period in variable menstrual cycles.\n\n2. STEP-BY-STEP SOLUTION:\nThe post-ovulatory luteal phase is constant at ~14 days. Therefore, ovulation occurs on Day (26 - 14) = Day 12. Accounting for sperm lifespan (~3 days) and ovum viability (~24-48 hours), the high-risk fertile period spans Day 9 to Day 15.\n\n3. FINAL ANSWER:\nOption C: Ovulation on Day 12, fertile window from Day 9 to Day 15\n\n4. WHY OTHER OPTIONS ARE WRONG:\nAssuming ovulation is always on Day 14 ignores the physiological variability of the follicular phase.",
